import sys

data = sys.stdin.read().split()
s = data[0]
n = len(s)
f = [[0] * (n + 1) for _ in range(n + 1)]
best = 0
for i in range(1, n + 1):
    for j in range(i + 1, n + 1):
        if s[i - 1] == s[j - 1]:
            f[i][j] = f[i - 1][j - 1] + 1
            if f[i][j] > best:
                best = f[i][j]
print(best)

